// Transaction Script Anti-Pattern when applied to complex logic:
async function upgradeSubscriptionScript(customerId: string, newPlanId: string) {
  const db = await getDbConnection();
  const sub = await db.query('SELECT * FROM subscriptions WHERE customer_id = $1', [customerId]);
  if (!sub.rows[0]) throw new Error('Not found');

  // Business invariant manually calculated in the script:
  const daysRemaining = calculateDaysRemaining(sub.rows[0].period_end);
  const credit = (sub.rows[0].price_cents / 30) * daysRemaining;
  const newPlan = await db.query('SELECT * FROM plans WHERE id = $1', [newPlanId]);
  const chargeAmount = newPlan.rows[0].price_cents - credit;

  await db.query('UPDATE subscriptions SET plan_id = $1 WHERE id = $2', [newPlanId, sub.rows[0].id]);
  await paymentGateway.charge(customerId, chargeAmount);
}

export type CurrencyCode = 'USD' | 'EUR' | 'GBP';

export class Money {
  readonly amountCents: number;
  readonly currency: CurrencyCode;

  private constructor(amountCents: number, currency: CurrencyCode) {
    if (!Number.isInteger(amountCents)) {
      throw new Error(`Money amount must be an integer (in cents). Received: ${amountCents}`);
    }
    this.amountCents = amountCents;
    this.currency = currency;
  }

  static fromCents(cents: number, currency: CurrencyCode): Money {
    return new Money(cents, currency);
  }

  static fromDollars(dollars: number, currency: CurrencyCode): Money {
    return new Money(Math.round(dollars * 100), currency);
  }

  static zero(currency: CurrencyCode): Money {
    return new Money(0, currency);
  }

  add(other: Money): Money {
    this.assertMatchingCurrency(other);
    return new Money(this.amountCents + other.amountCents, this.currency);
  }

  subtract(other: Money): Money {
    this.assertMatchingCurrency(other);
    return new Money(this.amountCents - other.amountCents, this.currency);
  }

  multiply(factor: number): Money {
    return new Money(Math.round(this.amountCents * factor), this.currency);
  }

  isGreaterThan(other: Money): boolean {
    this.assertMatchingCurrency(other);
    return this.amountCents > other.amountCents;
  }

  equals(other: Money): boolean {
    return this.amountCents === other.amountCents && this.currency === other.currency;
  }

  private assertMatchingCurrency(other: Money): void {
    if (this.currency !== other.currency) {
      throw new Error(`Currency mismatch: cannot operate between ${this.currency} and ${other.currency}`);
    }
  }
}

export class BillingPeriod {
  readonly start: Date;
  readonly end: Date;

  constructor(start: Date, end: Date) {
    if (start >= end) {
      throw new Error(`Invalid billing period: start (${start.toISOString()}) must precede end (${end.toISOString()})`);
    }
    this.start = new Date(start.getTime());
    this.end = new Date(end.getTime());
  }

  totalDurationDays(): number {
    const diffMs = this.end.getTime() - this.start.getTime();
    return Math.max(1, Math.ceil(diffMs / (1000 * 60 * 60 * 24)));
  }

  remainingDurationDays(asOf: Date): number {
    if (asOf < this.start) return this.totalDurationDays();
    if (asOf >= this.end) return 0;
    const diffMs = this.end.getTime() - asOf.getTime();
    return Math.ceil(diffMs / (1000 * 60 * 60 * 24));
  }

  remainingFraction(asOf: Date): number {
    const total = this.totalDurationDays();
    const remaining = this.remainingDurationDays(asOf);
    return remaining / total;
  }
}

export interface BillingPlan {
  readonly id: string;
  readonly name: string;
  readonly price: Money;
}

export interface ProrationCalculation {
  readonly unusedCredit: Money;
  readonly newPlanProratedCost: Money;
  readonly netAmountDue: Money;
}

export type SubscriptionStatus = 'ACTIVE' | 'PAST_DUE' | 'CANCELLED';

export class Subscription {
  readonly id: string;
  readonly customerId: string;
  private _status: SubscriptionStatus;
  private _currentPlan: BillingPlan;
  private _currentPeriod: BillingPeriod;

  constructor(
    id: string,
    customerId: string,
    initialPlan: BillingPlan,
    period: BillingPeriod,
    status: SubscriptionStatus = 'ACTIVE'
  ) {
    this.id = id;
    this.customerId = customerId;
    this._currentPlan = initialPlan;
    this._currentPeriod = period;
    this._status = status;
  }

  get status(): SubscriptionStatus { return this._status; }
  get currentPlan(): BillingPlan { return this._currentPlan; }
  get currentPeriod(): BillingPeriod { return this._currentPeriod; }

  calculateUpgradeProration(newPlan: BillingPlan, effectiveDate: Date): ProrationCalculation {
    if (this._status !== 'ACTIVE') {
      throw new Error(`Cannot upgrade subscription in status: ${this._status}`);
    }
    if (this._currentPlan.id === newPlan.id) {
      throw new Error(`Customer is already subscribed to plan: ${newPlan.name}`);
    }

    const remainingFraction = this._currentPeriod.remainingFraction(effectiveDate);

    // 1. Calculate credit for unspent portion of the current plan
    const unusedCredit = this._currentPlan.price.multiply(remainingFraction);

    // 2. Calculate prorated cost of the new plan for the remainder of the cycle
    const newPlanProratedCost = newPlan.price.multiply(remainingFraction);

    // 3. Determine net balance due (zero if credit exceeds new cost)
    const netCents = Math.max(0, newPlanProratedCost.amountCents - unusedCredit.amountCents);
    const netAmountDue = Money.fromCents(netCents, newPlan.price.currency);

    return { unusedCredit, newPlanProratedCost, netAmountDue };
  }

  applyPlanUpgrade(newPlan: BillingPlan, effectiveDate: Date): ProrationCalculation {
    const proration = this.calculateUpgradeProration(newPlan, effectiveDate);
    this._currentPlan = newPlan;
    return proration;
  }
}

export interface SubscriptionRepository {
  findById(id: string): Promise<Subscription | null>;
  save(subscription: Subscription): Promise<void>;
}

export interface PaymentGateway {
  charge(customerId: string, amount: Money, description: string): Promise<{ transactionId: string }>;
}

export interface NotificationService {
  sendReceipt(customerId: string, amount: Money, planName: string): Promise<void>;
}

export class SubscriptionBillingService {
  constructor(
    private readonly subRepo: SubscriptionRepository,
    private readonly paymentGateway: PaymentGateway,
    private readonly notifications: NotificationService
  ) {}

  async upgradePlan(
    subscriptionId: string,
    newPlan: BillingPlan,
    effectiveDate: Date = new Date()
  ): Promise<{ transactionId: string | null; proration: ProrationCalculation }> {
    // 1. Load Aggregate
    const subscription = await this.subRepo.findById(subscriptionId);
    if (!subscription) {
      throw new Error(`Subscription not found: ${subscriptionId}`);
    }

    // 2. Execute Domain Operation (Invariants protected inside entity)
    const proration = subscription.applyPlanUpgrade(newPlan, effectiveDate);

    // 3. Infrastructure Side Effect: Payment processing
    let transactionId: string | null = null;
    if (proration.netAmountDue.amountCents > 0) {
      const chargeResult = await this.paymentGateway.charge(
        subscription.customerId,
        proration.netAmountDue,
        `Prorated upgrade to ${newPlan.name}`
      );
      transactionId = chargeResult.transactionId;
    }

    // 4. Persistence
    await this.subRepo.save(subscription);

    // 5. Asynchronous notification
    if (transactionId) {
      await this.notifications.sendReceipt(
        subscription.customerId,
        proration.netAmountDue,
        newPlan.name
      );
    }

    return { transactionId, proration };
  }
}
